const uint32_t hash = std::hash<std::string>{}(std::string(key.data(), key.size()));
const uint32_t delta = (hash >> 17) | (hash << 15); // Rotate right 17 bits
for (size_t i = 0; i < num_probes; ++i) {
  const uint32_t bit_index = hash % bits;
